/* prog17_whitespace_trim.c
 *
 * Re‑implementation of the original binary’s functionality.
 * The program receives at most one command‑line argument.
 * It trims leading and trailing whitespace, collapses any
 * internal run of whitespace characters to a single space,
 * limits the processed input to 1024 characters, and prints
 * the resulting string.  If the result is empty (or no
 * argument is supplied) it prints the literal string "EMPTY".
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define MAX_INPUT 1024          /* 0x400 bytes – same limit as the original */
#define MAX_OUTPUT (MAX_INPUT + 1)

int main(int argc, char *argv[])
{
    const char *src;
    size_t src_len;
    char out[MAX_OUTPUT];
    size_t out_idx = 0;
    int  have_output = 0;      /* whether we have already placed a non‑space char */
    int  in_ws = 0;            /* currently inside a run of whitespace */

    /* If no argument is given, treat the input as an empty string. */
    if (argc < 2) {
        src = "";
    } else {
        src = argv[1];
    }

    /* Process at most MAX_INPUT characters, matching the original limit. */
    src_len = strnlen(src, MAX_INPUT);

    for (size_t i = 0; i < src_len; ++i) {
        unsigned char c = (unsigned char)src[i];

        if (c == ' ' || c == '\t' || c == '\n' ||
            c == '\r' || c == '\v' || c == '\f') {
            /* Remember that we are in whitespace; the actual space will be
               emitted only when a non‑whitespace character follows. */
            in_ws = 1;
        } else {
            /* If we have just left a whitespace run and we already have
               output, emit a single space to collapse the run. */
            if (in_ws && have_output) {
                out[out_idx++] = ' ';
            }
            out[out_idx++] = c;
            have_output = 1;
            in_ws = 0;
        }
    }

    if (out_idx == 0) {
        puts("EMPTY");
    } else {
        out[out_idx] = '\0';
        puts(out);
    }

    return 0;
}
